import threading


class VersionedCache:
    def __init__(self):
        self._entries = {}
        self._lock = threading.Lock()

    def compare_and_set(self, key, expected_version, new_value):
        with self._lock:
            current = self._entries.get(key)
            if current is None or current[1] != expected_version:
                return False
            self._entries[key] = (new_value, expected_version + 1)
            return True

    def refresh(self, key, loader):
        with self._lock:
            current = self._entries.get(key)
            if current is None:
                return False
            value, version = current

        new_value = loader(value)
        return self.compare_and_set(key, version, new_value)
